DEFAULT_UPSTREAM_NT = 45


def motif_matches(pattern: str, seq: str) -> bool:
    pattern = pattern.upper()
    seq = seq.upper()
    if len(pattern) != len(seq):
        return False
    for p, s in zip(pattern, seq):
        if p == "X":
            continue
        if p != s:
            return False
    return True


def _coding_upstream(seq: str, g: dict, *, upstream_nt: int = DEFAULT_UPSTREAM_NT) -> Optional[str]:
    if g["strand"] == "+":
        lo, hi = int(g["start"]) - upstream_nt, int(g["start"])
        if lo < 0 or hi > len(seq):
            return None
        return seq[lo:hi].upper()
    lo, hi = int(g["end"]), int(g["end"]) + upstream_nt
    if lo < 0 or hi > len(seq):
        return None
    return reverse_complement_dna(seq[lo:hi]).upper()


def prodigal_rbs_bin_from_upstream(region: str) -> int:
    """Return highest-priority matching bin for a 5'->3' upstream region ending before the start codon."""
    region = region.upper()
